excels.excel:

EXPORT WITH SHEET="材料退货单", HEADER=true,
    MAPPING={"a":"物料编码","b":"物料名称","c":"规格型号","d":"退货数量","e":"单价","f":"退货金额","g":"退货原因"},
    FORMAT={"d":"#,##0","e":"#,##0.00","f":"#,##0.00"},
    FORMULAS={
        F2:'D2*E2',F3:'D3*E3',F4:'D4*E4',F5:'D5*E5',F6:'D6*E6',
        D7:'SUM(D2:D6)',F7:'SUM(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    }
